import{_ as t,o as e,c as r,a2 as s}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"インデックス","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/settings/index-drives.md","filePath":"ja-JP/user-guide/settings/index-drives.md","lastUpdated":1785993908000}'),n={name:"ja-JP/user-guide/settings/index-drives.md"};function a(i,o,l,d,g,c){return e(),r("div",null,[...o[0]||(o[0]=[s('<h1 id="インデックス" tabindex="-1">インデックス <a class="header-anchor" href="#インデックス" aria-label="Permalink to &quot;インデックス&quot;">​</a></h1><p>5つのタブがあり、順に <strong>ローカルドライブ</strong>、<strong>ネットワークドライブ</strong>、<strong>WSL</strong>（ディストリビューションが検出された場合のみ表示）、<strong>フォルダー</strong>、<strong>除外ルール</strong> です。</p><h2 id="ローカルドライブ" tabindex="-1">ローカルドライブ <a class="header-anchor" href="#ローカルドライブ" aria-label="Permalink to &quot;ローカルドライブ&quot;">​</a></h2><ul><li>インデックス済みのドライブ数とアイテム数をまとめたステータスカードと、完全な再スキャンを行う <strong>インデックスの再構築</strong> ボタン。</li><li>ローカルドライブごとに1行：<strong>有効/無効チェックボックス</strong>、ドライブ名、ファイルシステム（NTFS/ReFS/...）、現在のステータス、インデックス済みアイテム数、そして行ごとの <strong>再構築</strong>/<strong>削除</strong> アクション。さらに、再構築中は <strong>停止</strong> アクションも表示されます（true NTFS のドライブを除く。そのスキャンには安全に中断できるポイントがないためです）。</li><li>NTFS と ReFS のドライブは Windows の USN ジャーナルを通じて変更を継続的に追跡します。それ以外のローカルファイルシステム（FAT32、exFAT など）には読み取れるジャーナルがないため、代わりに変更を直接監視します。いずれの方式でも手動での再構築が必要になることはほとんどありませんが、何かが同期していないように見える場合に備えて用意されています。また、再構築が中断された場合（停止された、またはアプリ/サービスがスキャン途中で再起動した場合）、次の再構築は最初からやり直すのではなく、中断した箇所から再開します。</li></ul><p>再構築中も検索はそのまま使えます。再構築中のドライブは新しいインデックスが用意できるまで以前のインデックスで応答を続け、ほかのドライブは影響を受けません。再構築のせいで結果が空になることはありません。</p><h2 id="ネットワークドライブ" tabindex="-1">ネットワークドライブ <a class="header-anchor" href="#ネットワークドライブ" aria-label="Permalink to &quot;ネットワークドライブ&quot;">​</a></h2><ul><li>ローカルドライブと同じステータスカードと <strong>インデックスの再構築</strong> ボタン。</li><li>マッピングされたネットワークドライブごとに1行：有効チェックボックス、パス/名前、ステータス（インデックス中 / 準備完了 / キャッシュ済み / 失敗 / 保留中 / 接続済み）、アイテム数、制限および <strong>更新モード</strong> ドロップダウン： <ul><li><strong>手動</strong> — オンデマンド（インデックスの再構築経由）でのみ更新されます。</li><li><strong>15分ごと</strong></li><li><strong>1時間ごと</strong></li><li><strong>毎日</strong></li></ul></li></ul><p>ネットワーク共有はローカルの NTFS ボリュームのような変更ジャーナルを公開していないため、リアルタイムではなくスケジュールに基づいて更新されます。スキャンエンジンにはブランチ祖先パススタックとシンボリックリンクの無限ループ検出メカニズムが組み込まれており、NAS/SMB 共有上に親ディレクトリを指すシンボリックリンクやリパースポイントが存在する場合でも、無限ループを自動的に防止してインデックス数を正確に維持します。</p><h2 id="wsl" tabindex="-1">WSL <a class="header-anchor" href="#wsl" aria-label="Permalink to &quot;WSL&quot;">​</a></h2><p>WSL ディストリビューションが少なくとも1つ検出された場合にのみ表示され、ネットワークドライブと同じ構成です（ステータスカード、<strong>インデックスの再構築</strong> ボタン、およびディストリビューションごとの1行にステータス/アイテム数/<strong>更新モード</strong>）。ディストリビューションは自動的に検出されるため、手動での「追加」手順はありません。</p><h2 id="フォルダー" tabindex="-1">フォルダー <a class="header-anchor" href="#フォルダー" aria-label="Permalink to &quot;フォルダー&quot;">​</a></h2><p>ドライブや共有全体ではなく、個々の任意のフォルダーをインデックスします。そのボリューム上の他のすべてを取り込まずに、1つのサブツリーだけをインデックスしたい場合に便利です。</p><ul><li><strong>フォルダーを追加</strong> ボタンでフォルダー選択ダイアログが開きます。<strong>インデックスの再構築</strong> ボタンはリスト内のすべてのフォルダーを再スキャンします。</li><li>追加したフォルダーごとに1行：有効チェックボックス、パス、ステータス、アイテム数、およびネットワークドライブと同じ <strong>更新モード</strong> ドロップダウン（手動 / 15分ごと / 1時間ごと / 毎日）。フォルダーはネットワーク共有と同様、継続的に追跡されるのではなくスケジュールに基づいてスキャンされます。</li><li>フォルダー選択ダイアログでは、選択ダイアログ内の <em>ネットワーク</em> から参照できる <strong>UNC ネットワーク共有パス</strong>（例：<code>\\\\server\\share</code>、またはその中のサブフォルダー）も指定できます。サーバー全体をマッピング済みネットワークドライブとして追加することなく、1つの共有やサブツリーだけをインデックスしたい場合に便利です。</li></ul><h2 id="除外ルール" tabindex="-1">除外ルール <a class="header-anchor" href="#除外ルール" aria-label="Permalink to &quot;除外ルール&quot;">​</a></h2><p>同じ構成の3つのサブタブがあります：単一エントリ用のテキストボックスと <strong>追加</strong> ボタン、既存ルールの一覧（それぞれ編集/削除可能）、および一括編集用の複数行テキストボックスと <strong>リストから生成</strong>/<strong>リストに適用</strong> ボタン。</p><ul><li><strong>パス除外</strong> — フルパスまたは環境変数（例：<code>D:\\Cache</code>、<code>%ProgramData%</code>）。</li><li><strong>グロブワイルドカード</strong> — <code>*</code>（ファイル名内の任意の文字列）、<code>?</code>（1文字）、<code>**</code>（再帰的なディレクトリ）。例：<code>*.tmp</code>、<code>**/node_modules/**</code>、<code>bin/**</code>。</li><li><strong>正規表現パターン</strong> — パス/ファイル名に対してマッチさせる任意の正規表現（部分一致）。例：<code>^\\.</code>（隠しファイル）、<code>~$</code>（Office の一時ファイル）、<code>\\.git\\</code>。</li></ul><p>除外はローカル、ネットワーク、フォルダーのインデックスすべてに適用され、除外設定を適用するとネットワークドライブ/フォルダーは自動的に再スキャンされます。</p>',17)])])}const p=t(n,[["render",a]]);export{h as __pageData,p as default};
